content.css:
/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
.selection-waterfall-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: var(--sw-font, 11px);
}
.selection-waterfall-root svg {
  shape-rendering: geometricPrecision;
}
/* ── KPI Strip ── */
.sw-kpi-strip {
  display: flex;
  gap: 0;
  padding: 6px 12px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-bg, #FFFFFF);
  flex-shrink: 0;
}
.sw-kpi-item {
  flex: 1;
  text-align: center;
  border-right: 1px solid var(--bf-rule, #E5E7EB);
  padding: 2px 8px;
}
.sw-kpi-item:last-child {
  border-right: none;
}
.sw-kpi-value {
  font-size: 16px;
  font-weight: 700;
  color: var(--bf-text, #242424);
  line-height: 1.2;
}
.sw-kpi-label {
  font-size: 9px;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-top: 1px;
}
.sw-kpi-value--selected {
  color: #15803d;
}
.sw-kpi-value--deferred {
  color: var(--bf-muted, #667079);
}
.sw-kpi-value--remaining {
  color: #2980b9;
}
.sw-kpi-value--whatif {
  color: #D97B29;
}
.sw-kpi-value--risk {
  color: #DC2626;
}
/* ── Axes ── */
.sw-axis .tick line {
  stroke: var(--bf-scroll-thumb, #D0D0D0);
  stroke-width: 0.5;
}
.sw-axis .tick text {
  fill: var(--bf-muted, #667079);
  font-size: 11px;
}
.sw-axis .domain {
  stroke: var(--bf-muted, #667079);
  stroke-width: 1;
}
.sw-axis-label {
  fill: var(--bf-text, #242424);
  font-size: 12px;
  font-weight: 600;
}
/* ── Bars ── */
.sw-bar {
  cursor: pointer;
  stroke: var(--bf-tile, #FFFFFF);
  stroke-width: 1;
  transition: opacity 0.15s ease;
}
.sw-bar:hover {
  filter: brightness(1.12);
  stroke-width: 1.5;
}
.sw-bar.dimmed {
  opacity: 0.25;
}
/* ── Data labels ── */
.sw-data-label {
  font-size: 9px;
  fill: var(--bf-muted, #667079);
  pointer-events: none;
  text-anchor: middle;
}
/* ── Cut line ── */
.sw-cut-line {
  stroke-dasharray: 6 3;
}
.sw-cut-label {
  font-size: 10px;
  font-weight: 600;
}
/* ── Budget zones and funded/deferred divider ── */
.sw-over-zone {
  opacity: 0.06;
}
.sw-headroom-zone {
  opacity: 0.08;
}
.sw-headroom-label {
  font-size: 11px;
  font-weight: 600;
  fill: var(--bf-muted, #667079);
}
.sw-cut-divider {
  stroke: var(--bf-muted, #667079);
  stroke-width: 1;
  stroke-dasharray: 2 3;
}
.sw-cut-tag {
  font-size: 10px;
  font-weight: 600;
  fill: var(--bf-muted, #667079);
}
/* ── Step connectors (waterfall running total) ── */
.sw-connector {
  stroke-dasharray: 2 2;
  opacity: 0.7;
}
/* ── Grid ── */
.sw-grid-line {
  stroke: var(--bf-rule, #E5E7EB);
  stroke-width: 0.5;
  stroke-dasharray: 3 3;
}
/* ── Legend ── */
.sw-legend {
  font-size: 11px;
  fill: var(--bf-muted, #667079);
}
.sw-legend-swatch {
  stroke: var(--bf-tile, #FFFFFF);
  stroke-width: 0.5;
}
/* ── Landing page ── */
.sw-landing {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--bf-muted, #667079);
  font-size: 14px;
  text-align: center;
  padding: 24px;
  box-sizing: border-box;
}
.sw-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--bf-muted, #667079);
  font-size: 12px;
  text-align: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
  letter-spacing: 0.2px;
}
/* ── Layout: toolbar · ask · KPI strip · body (chart | rail | panel) ── */
.sw-content {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  box-sizing: border-box;
  padding-bottom: 24px;
  /* licence badge clear-zone */
}
.sw-body {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: row;
}
.sw-chart-col {
  position: relative;
  flex: 1;
  min-width: 0;
  min-height: 0;
}
.sw-chart-col svg {
  display: block;
}
.sw-bar--scoped {
  stroke: #E8612A !important;
  stroke-width: 2 !important;
}
/* ── Toolbar ── */
.sw-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 5px 12px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  font-size: var(--sw-tb-font, 11px);
  color: var(--bf-text, #242424);
  flex-shrink: 0;
  flex-wrap: wrap;
}
.sw-toolbar__right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.sw-howto {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  flex: 1 1 260px;
  color: var(--bf-muted, #667079);
  line-height: 1.35;
}
.sw-howto__label {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: calc(var(--sw-tb-font, 11px) - 1.5px);
  color: var(--sw-insight-accent, #E8612A);
  white-space: nowrap;
}
.sw-howto__text {
  min-width: 0;
}
.sw-howto__x {
  border: 0;
  background: transparent;
  color: var(--bf-muted, #667079);
  cursor: pointer;
  font: inherit;
  padding: 0 2px;
}
.sw-howto__x:hover {
  color: var(--bf-text, #242424);
}
.sw-whatif {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 4px;
  background: var(--bf-surface, #F8F9FB);
}
.sw-whatif--active {
  border-color: #D97B29;
  background: rgba(217, 123, 41, 0.08);
}
.sw-whatif__label {
  color: var(--bf-muted, #667079);
  white-space: nowrap;
}
.sw-whatif__range {
  width: 130px;
  accent-color: #D97B29;
  margin: 0;
}
.sw-whatif__value {
  font-weight: 700;
  min-width: 44px;
  font-variant-numeric: tabular-nums;
}
.sw-whatif__reset {
  border: 0;
  background: transparent;
  color: #9a5418;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  padding: 0;
  text-decoration: underline;
}
.sw-tbtn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 4px;
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #667079);
  font: inherit;
  cursor: pointer;
  transition: all 0.12s ease;
}
.sw-tbtn:hover {
  color: var(--bf-text, #242424);
  border-color: var(--bf-muted, #667079);
}
.sw-tbtn:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.sw-tbtn--active {
  background: rgba(232, 97, 42, 0.12);
  border-color: var(--sw-insight-accent, #E8612A);
  color: var(--bf-strong, #1F2A44);
  font-weight: 600;
}
.sw-tbtn__icon {
  font-size: 12px;
  line-height: 1;
}
/* Info button: suite chrome, fixed (see BFusion-Apps/CLAUDE.md). */
.sw-info {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E3E6EC;
  background: #FFFFFF;
  color: #6B7280;
  font-family: inherit;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  line-height: 1;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.12s ease;
}
.sw-info:hover {
  background: #E8612A;
  color: #FFFFFF;
  transform: scale(1.05);
}
.sw-info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.sw-info-pop {
  position: absolute;
  top: 34px;
  right: 10px;
  z-index: 30;
  width: 340px;
  max-width: calc(100% - 20px);
  max-height: 70%;
  overflow-y: auto;
  padding: 10px 12px;
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-text, #242424);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  box-shadow: 0 6px 20px var(--bf-shadow, rgba(15, 23, 42, 0.12));
  font-size: 11px;
  line-height: 1.45;
}
.sw-info-pop__title {
  font-weight: 700;
  font-size: 12px;
  padding-bottom: 5px;
  margin-bottom: 6px;
  border-bottom: 2px solid var(--sw-insight-accent, #E8612A);
}
.sw-info-pop__list {
  margin: 0;
  padding-left: 16px;
}
.sw-info-pop__list li {
  margin-bottom: 4px;
}
/* ── Ask: question chips (same as KPI Grid) ── */
.sw-ask {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 5px 12px 6px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  flex-shrink: 0;
  font-size: var(--sw-tb-font, 11px);
}
.sw-ask__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.sw-ask__label {
  font-size: calc(var(--sw-tb-font, 11px) - 0.5px);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--sw-insight-accent, #E8612A);
  margin-right: 2px;
}
.sw-ask__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 5px 3px 11px;
  border-radius: 999px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-surface-alt, #F4F5F7);
  color: var(--bf-text, #242424);
  font: inherit;
  cursor: pointer;
  transition: border-color 0.12s ease, background 0.12s ease;
}
.sw-ask__chip:hover {
  border-color: var(--sw-insight-accent, #E8612A);
}
.sw-ask__chip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.sw-ask__chip--active {
  background: rgba(232, 97, 42, 0.12);
  border-color: var(--sw-insight-accent, #E8612A);
  color: var(--bf-strong, #1F2A44);
  font-weight: 600;
}
.sw-ask__count {
  min-width: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  font-size: calc(var(--sw-tb-font, 11px) - 1px);
  font-weight: 700;
  line-height: 16px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.sw-ask__count--none {
  color: #16a34a;
}
.sw-ask__chip--active .sw-ask__count {
  background: var(--sw-insight-accent, #E8612A);
  border-color: var(--sw-insight-accent, #E8612A);
  color: #FFFFFF;
}
.sw-ask__answer {
  display: flex;
  align-items: baseline;
  gap: 8px;
  color: var(--bf-strong, #1F2A44);
  font-size: calc(var(--sw-tb-font, 11px) + 1px);
}
.sw-ask__arrow {
  color: var(--sw-insight-accent, #E8612A);
  font-weight: 700;
}
.sw-ask__text {
  flex: 1;
  font-weight: 600;
}
.sw-ask__clear {
  border: 0;
  background: transparent;
  color: var(--bf-muted, #667079);
  cursor: pointer;
  font: inherit;
  padding: 0 4px;
}
.sw-ask__clear:hover {
  color: var(--bf-text, #242424);
}
/* ── Focus ── */
.sw-why__tag {
  font-size: 9px;
  font-weight: 700;
  fill: #D97706;
  pointer-events: none;
}
.sw-focus-empty {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 20px;
  text-align: center;
  color: var(--bf-muted, #667079);
  font-size: 12px;
}
.sw-focus-empty__title {
  font-size: 15px;
  font-weight: 600;
  color: #16a34a;
}
/* ── Callouts ── */
.sw-callout {
  cursor: help;
}
.sw-callout text {
  pointer-events: none;
}
/* ── Insight rail: suite chrome, fixed (see BFusion-Apps/CLAUDE.md) ── */
.bfusion-insight-strip {
  background: var(--bf-surface-alt, #F4F5F7);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  color: var(--bf-muted, #667079);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
  flex: 0 0 26px;
  width: 26px;
}
.bfusion-insight-strip__arrow {
  font-size: 10px;
  color: #D97B29;
  line-height: 1;
}
.bfusion-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 0.18em;
  font-size: 9px;
  font-weight: 650;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
}
.bfusion-insight-strip:hover,
.bfusion-insight-strip:focus {
  background: var(--bf-rule, #E5E7EB);
  color: var(--bf-text, #242424);
  outline: none;
}
.bfusion-insight-strip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
/* ── Insight panel ── */
.sw-panel {
  flex: 0 0 260px;
  width: 260px;
  max-width: 320px;
  box-sizing: border-box;
  padding: 8px 10px;
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  background: linear-gradient(180deg, var(--bf-tile, #FFFFFF) 0%, var(--bf-surface, #F8F9FB) 100%);
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  font-size: var(--sw-insight-font, 11px);
  color: var(--bf-text, #242424);
}
.sw-panel [data-tone="good"] {
  --tone: #16a34a;
}
.sw-panel [data-tone="warn"] {
  --tone: #d97706;
}
.sw-panel [data-tone="bad"] {
  --tone: #dc2626;
}
.sw-panel [data-tone="info"] {
  --tone: #1e40af;
}
.bfusion-scope-chip {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  padding: 2px 8px;
  margin: 0 4px 6px 0;
  border: 1px solid rgba(217, 123, 41, 0.35);
  border-radius: 999px;
  background: rgba(217, 123, 41, 0.08);
  color: #9a5418;
  font-family: inherit;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bfusion-scope-chip:hover {
  background: rgba(217, 123, 41, 0.16);
}
.bfusion-scope-chip__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-scope-chip__x {
  color: #b1712f;
  font-weight: 700;
}
.sw-panel__header {
  padding-bottom: 6px;
  margin-bottom: 8px;
  border-bottom: 2px solid var(--sw-insight-accent, #E8612A);
}
.sw-panel__title {
  font-size: var(--sw-insight-header-font, 13px);
  font-weight: 700;
  color: var(--bf-text, #242424);
}
.sw-panel__sub {
  font-size: calc(var(--sw-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
  margin-top: 1px;
}
.sw-verdict {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  margin-bottom: 8px;
  border-radius: 6px;
  background-color: color-mix(in srgb, var(--tone) 8%, var(--bf-tile, #FFFFFF));
  border: 1px solid color-mix(in srgb, var(--tone) 30%, var(--bf-tile, #FFFFFF));
  border-left: 4px solid var(--tone);
}
.sw-verdict__badge {
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background-color: var(--tone);
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: 700;
}
.sw-verdict__text {
  min-width: 0;
}
.sw-verdict__title {
  font-size: calc(var(--sw-insight-font, 11px) + 1px);
  font-weight: 700;
  line-height: 1.3;
  color: color-mix(in srgb, var(--tone) 70%, var(--bf-text, #242424));
}
.sw-verdict__sub {
  font-size: calc(var(--sw-insight-font, 11px) - 1px);
  color: var(--bf-muted, #667079);
  margin-top: 2px;
  line-height: 1.35;
}
.sw-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 8px;
}
.sw-tile {
  padding: 5px 8px;
  border-radius: 4px;
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-left: 3px solid var(--tone);
}
.sw-tile__val {
  font-size: calc(var(--sw-insight-font, 11px) + 3px);
  font-weight: 700;
  color: var(--bf-text, #242424);
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
}
.sw-tile__lbl {
  font-size: calc(var(--sw-insight-font, 11px) - 2px);
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-top: 1px;
}
.sw-health {
  margin-bottom: 8px;
}
.sw-health__bar {
  display: flex;
  height: 10px;
  border-radius: 5px;
  overflow: hidden;
  background: var(--bf-rule, #E5E7EB);
}
.sw-health__seg {
  height: 100%;
}
.sw-health__seg--funded {
  background: #26a85d;
}
.sw-health__seg--free {
  background: rgba(38, 168, 93, 0.25);
}
.sw-health__seg--deferred {
  background: #9CA3AF;
}
.sw-health__legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
  margin-top: 4px;
  font-size: calc(var(--sw-insight-font, 11px) - 1.5px);
  color: var(--bf-muted, #667079);
}
.sw-health__legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.sw-health__dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 2px;
}
.sw-panel__section {
  margin: 10px 0 6px;
  font-size: calc(var(--sw-insight-font, 11px) - 1px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--sw-insight-accent, #E8612A);
}
.sw-card {
  border-radius: 6px;
  padding: 8px;
  margin-bottom: 8px;
  background-color: color-mix(in srgb, var(--tone) 6%, var(--bf-tile, #FFFFFF));
  border: 1px solid color-mix(in srgb, var(--tone) 28%, var(--bf-tile, #FFFFFF));
}
.sw-card[data-tone="info"] {
  background-color: var(--bf-tile, #FFFFFF);
  border-color: var(--bf-rule, #E5E7EB);
}
.sw-card--active {
  box-shadow: 0 0 0 2px #D97B29;
}
.sw-card__head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 5px;
}
.sw-card__icon {
  font-size: 12px;
  line-height: 1;
  color: var(--tone);
}
.sw-card__title {
  font-size: calc(var(--sw-insight-font, 11px) - 1px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: color-mix(in srgb, var(--tone) 70%, var(--bf-text, #242424));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sw-card__headline {
  font-size: calc(var(--sw-insight-font, 11px) + 0.5px);
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 3px;
}
.sw-card__item {
  font-size: calc(var(--sw-insight-font, 11px) - 0.5px);
  line-height: 1.45;
  padding: 1px 0;
  color: var(--bf-text, #242424);
}
.sw-card__item--muted {
  color: var(--bf-muted, #667079);
  font-style: italic;
}
.sw-card__action {
  font-weight: 600;
}
.sw-card__filter {
  appearance: none;
  margin-top: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--tone) 40%, var(--bf-tile, #FFFFFF));
  background: var(--bf-tile, #FFFFFF);
  color: color-mix(in srgb, var(--tone) 75%, var(--bf-text, #242424));
  font-family: inherit;
  font-size: 10px;
  font-weight: 600;
  cursor: pointer;
}
.sw-card__filter:hover,
.sw-card__filter[aria-pressed="true"] {
  background: color-mix(in srgb, var(--tone) 12%, var(--bf-tile, #FFFFFF));
}
.sw-card__filter:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.sw-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.sw-list__row {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 0;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  cursor: pointer;
}
.sw-list__row:hover .sw-list__name {
  color: var(--sw-insight-accent, #E8612A);
}
.sw-list__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
  background: #26a85d;
}
.sw-list__dot[data-state="deferred"] {
  background: #9CA3AF;
}
.sw-list__name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sw-list__val {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
/* ── Responsive ── */
.selection-waterfall-root.wl-medium .sw-panel {
  flex-basis: 220px;
  width: 220px;
}
.selection-waterfall-root.wl-medium .sw-whatif__range {
  width: 100px;
}
.selection-waterfall-root.wl-narrow .sw-panel {
  position: absolute;
  top: 0;
  right: 26px;
  bottom: 0;
  z-index: 20;
  width: 260px;
  max-width: calc(100% - 40px);
  box-shadow: -4px 0 16px var(--bf-shadow, rgba(15, 23, 42, 0.12));
}
.selection-waterfall-root.wl-narrow .sw-whatif__range {
  width: 80px;
}
.selection-waterfall-root.wl-narrow .sw-kpi-value {
  font-size: 13px;
}
.selection-waterfall-root.wl-narrow .sw-ask__row {
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: thin;
}
.selection-waterfall-root.wl-narrow .sw-ask__chip {
  flex-shrink: 0;
}
.selection-waterfall-root.wl-narrow .sw-howto {
  display: none !important;
}
/* ── License Badge & Watermark ── */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
